import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

export const E2E_DIR = fileURLToPath(new URL('../', import.meta.url));
/** Everything generated by a run (fixtures, sessions, reports); ignored by git. */
export const OUTPUT_DIR = join(E2E_DIR, '.output');
export const AUTH_DIR = join(OUTPUT_DIR, 'auth');

/** Browser sessions prepared by global setup, by persona. */
export const STORAGE = {
  admin: join(AUTH_DIR, 'admin.json'),
  learner: join(AUTH_DIR, 'learner.json'),
  device: join(AUTH_DIR, 'device.json'),
} as const;

export type Persona = keyof typeof STORAGE | 'anon';

/** Sessions of the second installation, used by the learner-screen specs (fixtures/learning.ts). */
export const LEARNING_STORAGE = {
  admin: join(AUTH_DIR, 'learning-admin.json'),
  device: join(AUTH_DIR, 'learning-device.json'),
} as const;
